#include "vae_axis.hpp"

#include "vae_core.h"  // generated by hls4ml (train_vae.py)

// Fully pipelined wrapper. Three dataflow processes overlap successive frames:
//
//   read_frame ──x_core──> vae_core (hls4ml, interval = reuse factor) ──recon──┐
//        └──────────── bypass FIFO (features + valid flag) ────────────> score_and_write
//
// Framing rules are unchanged from deep_svdd_axis: a frame with an early TLAST, a late
// TLAST or a byte mask other than 4'hF produces no score. Malformed frames still flow
// through vae_core (with valid = false) so every process handles exactly one item per
// frame, which keeps the dataflow region free-running under ap_ctrl_none.

namespace {

constexpr int kFeatureCount = 8;
// vae_core holds about latency / interval = 138 / 16 ≈ 9 frames in flight; the bypass
// FIFO must hold at least that many so the reader never waits on the scorer.
constexpr int kBypassDepth = 16;
using score_t = ap_ufixed<64, 32>;
// Exact difference of a 16-fractional-bit feature and a reconstruction with <= 16 fractional bits.
using diff_t = ap_fixed<27, 11>;

struct frame_t {
    input_t x[kFeatureCount];
    bool valid;
};

void read_frame(hls::stream<vae_feature_beat_t>& in, input_t x_core[kFeatureCount],
                hls::stream<frame_t>& bypass) {
    frame_t f;
    for (int i = 0; i < kFeatureCount; ++i) {
#pragma HLS UNROLL
        f.x[i] = 0;
    }
    ap_uint<4> valid_bytes = 0xf;
    bool last = false;
    int beats = 0;

read_beats:
    for (int i = 0; i < kFeatureCount; ++i) {
#pragma HLS PIPELINE II=1
        const vae_feature_beat_t beat = in.read();
        valid_bytes &= beat.keep & beat.strb;
        f.x[i].range(24, 0) = beat.data.range(24, 0);
        beats = i + 1;
        last = beat.last;
        if (last) break;  // early TLAST ends (and invalidates) the frame
    }
    if (!last) {
    drain:  // oversized frame: discard through its TLAST
        do {
#pragma HLS PIPELINE II=1
            last = in.read().last;
        } while (!last);
        f.valid = false;
    } else {
        f.valid = beats == kFeatureCount && valid_bytes == 0xf;
    }

    for (int i = 0; i < kFeatureCount; ++i) {
#pragma HLS UNROLL
        x_core[i] = f.x[i];
    }
    bypass.write(f);
}

void score_and_write(const result_t recon[kFeatureCount], hls::stream<frame_t>& bypass,
                     hls::stream<vae_score_beat_t>& out) {
#pragma HLS PIPELINE II=1
    const frame_t f = bypass.read();
    score_t sum = 0;
    for (int i = 0; i < kFeatureCount; ++i) {
#pragma HLS UNROLL
        const diff_t d = diff_t(f.x[i]) - diff_t(recon[i]);
        const ap_fixed<54, 22> sq = d * d;  // exact: 32 fractional bits
        sum += score_t(sq);
    }
    if (f.valid) {
        vae_score_beat_t result;
        result.data = sum.range(63, 0);
        result.keep = 0xff;
        result.strb = 0xff;
        result.last = 1;
        out.write(result);
    }
}

}  // namespace

void vae_axis(hls::stream<vae_feature_beat_t>& s_axis_features,
              hls::stream<vae_score_beat_t>& m_axis_score) {
#pragma HLS INTERFACE axis port=s_axis_features register_mode=both
#pragma HLS INTERFACE axis port=m_axis_score register_mode=both
#pragma HLS INTERFACE ap_ctrl_none port=return
#pragma HLS DATAFLOW

    static_assert(input_t::width == 25 && input_t::iwidth == 9,
                  "The feature stream carries signed fixed-point values with 16 fractional bits");
    static_assert(result_t::width - result_t::iwidth <= 16,
                  "Reconstruction must have at most 16 fractional bits for an exact score");

    input_t x_core[kFeatureCount];
#pragma HLS ARRAY_RESHAPE variable=x_core complete dim=0
    result_t recon[kFeatureCount];
#pragma HLS ARRAY_PARTITION variable=recon complete dim=0
    hls::stream<frame_t, kBypassDepth> bypass;

    read_frame(s_axis_features, x_core, bypass);
    vae_core(x_core, recon);
    score_and_write(recon, bypass, m_axis_score);
}
